                .run(DepsOptions {
                    auto_only: true, // Only run providers with auto=true
                    dry_run: self.dry_run,
                    env,
                    env_remove,
                    ..Default::default()
    }

    // ============================================================================
    // High-level workflow methods
    // ============================================================================

    /// Prepare tasks: fetch remote tasks and create dependency graph
    /// Dependencies should already be resolved via resolve_depends() before calling this.
    async fn prepare_tasks(&mut self, config: &Arc<Config>, mut tasks: Vec<Task>) -> Result<Deps> {
        let fetcher = crate::task::task_fetcher::TaskFetcher::new(self.no_cache);
        fetcher.fetch_tasks(config, &mut tasks).await?;
        let mut tasks = Deps::new(config, tasks).await?;
        tasks.mark_ambiguous_prefixes();
        self.is_linear = tasks.is_linear();
        Ok(tasks)
    }

    /// Initialize output handler and validate tasks
    fn setup_output_and_validate(&mut self, tasks: &Deps) -> Result<()> {
        // Initialize OutputHandler AFTER is_linear is determined
        let output_config = crate::task::task_output_handler::OutputHandlerConfig {
            output: self.output,
            silent: self.silent,
            quiet: self.quiet,
            raw: self.raw,
            is_linear: self.is_linear,
            jobs: self.jobs,
        };
        self.output_handler = Some(OutputHandler::new(output_config));

        // Spawn the timed-output printer if any task resolves to the Timed style
        // (run-wide default OR a per-task `output = "timed"` override).
        let any_timed = tasks
            .all()
            .any(|task| self.output(Some(task)) == TaskOutput::Timed);
        if any_timed {
            let timed_outputs = self.output_handler.as_ref().unwrap().timed_outputs.clone();
            tokio::spawn(async move {
                let mut interval = tokio::time::interval(Duration::from_millis(100));
                loop {
                    {
                        let mut outputs = timed_outputs.lock().unwrap();
                        for (prefix, out) in outputs.clone() {
                            let (time, lines) = out;
                            if time.elapsed().unwrap().as_secs() >= 1 {
                                for line in lines {
                                    if console::colors_enabled() {
                                        prefix_println!(prefix, "{line}\x1b[0m");
                                    } else {
                                        prefix_println!(prefix, "{line}");
                                    }
                                }
                                outputs.shift_remove(&prefix);
                            }
                        }
                    }
                    interval.tick().await;
                }
            });
        }

        // Validate and initialize task output. In creation order: keep-order
        // hands out its output slots here, and the same order is used for the
        // tasks a run entry injects later, so the two agree by construction.
        for task in tasks.all_in_creation_order() {
            self.validate_task(task)?;
            self.output_handler.as_mut().unwrap().init_task(task);
        }

        Ok(())
    }

    /// Create TaskExecutor after tool installation to ensure caches are populated
    fn setup_executor(&mut self) -> Result<()> {
        let executor_config = crate::task::task_executor::TaskExecutorConfig {
            force: self.force,
            cd: self.cd.clone(),
            shell: self.shell.clone(),
            tool: self.tool.clone(),
            timings: self.timings,
            continue_on_error: self.continue_on_error,
            dry_run: self.dry_run,
            skip_deps: self.skip_deps,
            task_cache: self.task_cache,
            task_cache_explain: self.task_cache_explain,
            task_cache_explain_json: self.task_cache_explain_json,
            sandbox: crate::sandbox::SandboxConfig::from_settings_and_cli(
                &Settings::get().sandbox,
                self.deny_all,
                crate::sandbox::SandboxConfig {
                    deny_read: self.deny_read,
                    deny_write: self.deny_write,
                    deny_net: self.deny_net,
                    deny_env: self.deny_env,
                    deny_process: false,
                    deny_temp_write: false,
                    allow_read: self.allow_read.clone(),
                    allow_write: self.allow_write.clone(),
                    allow_net: self.allow_net.clone(),
                    allow_env: self.allow_env.clone(),
                    pass_through_env: vec![],
                    cache_env: vec![],
                    symlinked_allow_paths: vec![],
                },
            ),
        };
        self.executor = Some(crate::task::task_executor::TaskExecutor::new(
            self.context_builder.clone(),
            self.output_handler.clone().unwrap(),
            executor_config,
        ));

        Ok(())
    }

    /// Collect and install all tools needed by tasks
    async fn install_task_tools(
        &self,
        config: &mut Arc<Config>,
        tasks: &Deps,
        previewed_tools: &HashSet<ToolVersion>,
    ) -> Result<()> {
        let installer = crate::task::task_tool_installer::TaskToolInstaller::new(
            &self.context_builder,
            &self.tool,
        );
        installer
            .install_tools(config, tasks, self.dry_run, previewed_tools)
            .await
    }

    // ============================================================================
    // Helper methods
    // ============================================================================

    fn eprint(&self, task: &Task, prefix: &str, line: &str) {
        self.output_handler
            .as_ref()
            .unwrap()
            .eprint(task, prefix, line);
    }

    fn output(&self, task: Option<&Task>) -> TaskOutput {
        self.output_handler.as_ref().unwrap().output(task)
    }

    fn jobs(&self) -> usize {
        self.output_handler.as_ref().unwrap().jobs()
    }

    fn is_stopping(&self) -> bool {
use crate::cli::args::ToolArg;
use crate::config::{Config, Settings};
use crate::task::task_context_builder::TaskContextBuilder;
use crate::task::task_helpers::canonicalize_path;
use crate::task::{Deps, Task};
use crate::toolset::{InstallOptions, ToolSource, ToolVersion, Toolset};
use eyre::Result;
use std::collections::HashSet;
use std::path::Path;
use std::sync::Arc;

/// Handles collection and installation of tools required by tasks
pub(crate) struct TaskToolInstaller<'a> {
    context_builder: &'a TaskContextBuilder,
    cli_tools: &'a [ToolArg],
}

impl<'a> TaskToolInstaller<'a> {
    pub(crate) fn new(context_builder: &'a TaskContextBuilder, cli_tools: &'a [ToolArg]) -> Self {
        Self {
            context_builder,
            cli_tools,
        }
    }

    /// Collect and install all tools needed by tasks
    pub(crate) async fn install_tools(
        &self,
        config: &mut Arc<Config>,
        tasks: &Deps,
        dry_run: bool,
        previewed_tools: &HashSet<ToolVersion>,
    ) -> Result<()> {
        let all_tasks: Vec<_> = tasks.all().collect();
        let all_tool_requests = self.collect_tool_requests(config, all_tasks).await?;

        // Build and install toolset
        let toolset = self
            .build_toolset(config, self.cli_tools.to_vec(), all_tool_requests)
            .await?;
        self.install_toolset(config, toolset, dry_run, previewed_tools)
            .await?;

        Ok(())
    }

    /// Collect every tool request needed to prepare the supplied tasks without
    /// executing their commands or dependency graphs.
    pub(crate) async fn collect_tool_requests<'t>(
        &self,
        config: &Arc<Config>,
        tasks: impl IntoIterator<Item = &'t Task>,
    ) -> Result<Vec<crate::toolset::ToolRequest>> {
        let tasks = tasks.into_iter().collect::<Vec<_>>();
        let mut requests = vec![];
        let mut seen_config_roots = HashSet::new();

        trace!("Collecting tools from {} tasks", tasks.len());

        for task in tasks {
            requests.extend(task.tool_args()?.into_iter().filter_map(|tool| tool.tvr));

            // Task execution combines task-level tools with the config hierarchy
            // that owns the task. Keep pre-installation consistent with that
            // environment, including file and monorepo tasks.
            let config_root = task
                .cf(config)
                .map(|task_cf| task_cf.config_root())
                .or_else(|| task.config_root.clone());
            if let Some(config_root) = config_root {
                let config_root = canonicalize_path(&config_root);
                if seen_config_roots.insert(config_root.clone()) {
                    requests.extend(
                        self.collect_tools_from_dir(&config_root, &task.name)
                            .await?,
                    );
                }
            }
        }

        Ok(requests)
    }

    /// Collect tools from config files found in a directory hierarchy
    async fn collect_tools_from_dir(
        &self,
        dir: &Path,
        task_name: &str,
    ) -> Result<Vec<crate::toolset::ToolRequest>> {
        let (config_paths, idiomatic_filenames) =
            crate::config::load_config_hierarchy_from_dir(dir).await?;
        let task_config_files =
            crate::config::load_config_files_from_paths(&config_paths, &idiomatic_filenames)
                .await?;

        let mut tool_requests: Vec<crate::toolset::ToolRequest> = vec![];
        let mut seen_tools: std::collections::HashSet<String> = std::collections::HashSet::new();

        for (source, cf) in task_config_files.iter() {
            let config_path = canonicalize_path(source);

            // Check cache first for this config file's tool request set
            let trs = {
                let cache = self
                    .context_builder
                    .tool_request_set_cache()
                    .read()
                    .expect("tool_request_set_cache RwLock poisoned");
                cache.get(&config_path).cloned()
            };

            let trs = if let Some(cached) = trs {
                trace!(
                    "Using cached tool request set from {}",
                    config_path.display()
                );
                cached
            } else {
                match cf.to_tool_request_set() {
                    Ok(trs) => {
                        let trs = Arc::new(trs);
                        let mut cache = self
                            .context_builder
                            .tool_request_set_cache()
                            .write()
                            .expect("tool_request_set_cache RwLock poisoned");
                        cache.insert(config_path.clone(), Arc::clone(&trs));
                        trace!("Cached tool request set from {}", config_path.display());
                        trs
                    }
                    Err(e) => {
                        warn!(
                            "Failed to parse tools from {} for task {}: {}",
                            source.display(),
                            task_name,
                            e
                        );
                        continue;
                    }
                }
            };

            for (ba, reqs) in trs.tools.iter() {
                let tool_key = ba.to_string();
                if !seen_tools.contains(&tool_key) {
                    trace!(
                        "Adding tool {} from {} for task {}",
                        ba,
                        source.display(),
                        task_name
                    );
                    tool_requests.extend(reqs.iter().cloned());
                    seen_tools.insert(tool_key);
                }
            }
        }

        trace!(
            "Found {} tool requests in config hierarchy for task {}",
            tool_requests.len(),
            task_name
        );

        Ok(tool_requests)
    }

    /// Build a toolset from CLI tools and collected tool requests
    async fn build_toolset(
        &self,
        config: &Arc<Config>,
        all_tools: Vec<ToolArg>,
        all_tool_requests: Vec<crate::toolset::ToolRequest>,
    ) -> Result<Toolset> {
        let source = ToolSource::Argument;
        let mut ts = Toolset::new(source.clone());

        // Add tools from CLI args and task.tools
        for tool_arg in all_tools {
            if let Some(tvr) = tool_arg.tvr {
                ts.add_version(tvr);
            }
        }

        // Add tools from config files
        for tr in all_tool_requests {
            trace!("Adding tool from config: {}", tr);
            ts.add_version(tr);
        }

        ts.resolve(config).await?;

        Ok(ts)
    }

    /// Install missing versions from the toolset
    async fn install_toolset(
        &self,
        config: &mut Arc<Config>,
        mut ts: Toolset,
        dry_run: bool,
        previewed_tools: &HashSet<ToolVersion>,
    ) -> Result<()> {
        if dry_run {
            for tvl in ts.versions.values_mut() {
                tvl.versions.retain(|tv| !previewed_tools.contains(tv));
            }
        }
        let (_, missing) = ts
            .install_missing_versions(
                config,
                &InstallOptions {
                    dry_run,
                    missing_args_only: !Settings::get().task.run_auto_install,
                    skip_auto_install: !Settings::get().task.run_auto_install
                        || !Settings::get().auto_install,
                    ..Default::default()
                },
            )
            .await?;
        if !dry_run && let Err(err) = crate::shims::ensure_lazy_shims(&missing) {
            warn!("failed to create shims for lazy tools: {err:#}");
        }

        Ok(())
    }
}

