use crate::cli::args::ToolArg;
use crate::config::{Config, Settings};
use crate::task::task_context_builder::TaskContextBuilder;
use crate::task::task_helpers::canonicalize_path;
use crate::task::task_list::{resolve_depends, split_task_spec};
use crate::task::{Deps, GetMatchingExt, RunEntry, Task, TaskLoadContext};
use crate::tera::contains_template_syntax;
use crate::toolset::{InstallOptions, ToolSource, ToolVersion, Toolset};
use eyre::Result;
use std::collections::{BTreeMap, HashSet};
use std::iter::once;
use std::path::Path;
use std::sync::Arc;

/// Handles collection and installation of tools required by tasks
pub(crate) struct TaskToolInstaller<'a> {
    context_builder: &'a TaskContextBuilder,
    cli_tools: &'a [ToolArg],
}

impl<'a> TaskToolInstaller<'a> {
    pub(crate) fn new(context_builder: &'a TaskContextBuilder, cli_tools: &'a [ToolArg]) -> Self {
        Self {
            context_builder,
            cli_tools,
        }
    }

    /// Collect and install all tools needed by tasks
    pub(crate) async fn install_tools(
        &self,
        config: &mut Arc<Config>,
        tasks: &Deps,
        dry_run: bool,
        previewed_tools: &HashSet<ToolVersion>,
    ) -> Result<()> {
        let all_tasks = self
            .collect_run_entry_tasks(config, tasks.all().cloned().collect())
            .await?;
        let all_tool_requests = self.collect_tool_requests(config, &all_tasks).await?;

        // Build and install toolset
        let toolset = self
            .build_toolset(config, self.cli_tools.to_vec(), all_tool_requests)
            .await?;
        self.install_toolset(config, toolset, dry_run, previewed_tools)
            .await?;

        Ok(())
    }

    /// Add tasks referenced by static `run` entries to the set whose tools are
    /// installed. These remain execution steps rather than dependency edges.
    async fn collect_run_entry_tasks(
        &self,
        config: &Arc<Config>,
        mut tasks: Vec<Task>,
    ) -> Result<Vec<Task>> {
        let mut seen: HashSet<Task> = tasks.iter().cloned().collect();
        let mut index = 0;

        while index < tasks.len() {
            let parent = tasks[index].clone();
            index += 1;
            let specs = parent
                .run()
                .iter()
                .flat_map(|entry| match entry {
                    RunEntry::SingleTask { task, .. } if !contains_template_syntax(task) => {
                        vec![task.clone()]
                    }
                    RunEntry::TaskGroup { tasks } => tasks
                        .iter()
                        .filter(|task| !contains_template_syntax(task))
                        .cloned()
                        .collect(),
                    _ => vec![],
                })
                .map(|spec| crate::task::resolve_task_pattern(&spec, Some(&parent)))
                .collect::<Vec<_>>();
            if specs.is_empty() {
                continue;
            }

            let ctx = TaskLoadContext::from_patterns(specs.iter().map(|spec| {
                let (name, _) = split_task_spec(spec);
                name
            }));
            let available = config.tasks_with_context(Some(&ctx)).await?;
            let available: BTreeMap<String, Task> = available
                .values()
                .flat_map(|task| {
                    task.aliases
                        .iter()
                        .map(|alias| (alias.to_string(), task.clone()))
                        .chain(once((task.name.clone(), task.clone())))
                })
                .collect();
            let mut referenced = vec![];
            for spec in specs {
                let (name, _) = split_task_spec(&spec);
                referenced.extend(
                    available
                        .get_matching(name)?
                        .into_iter()
                        .map(|task| (*task).clone()),
                );
            }

            for task in resolve_depends(config, referenced).await? {
                if seen.insert(task.clone()) {
                    tasks.push(task);
                }
            }
        }

        Ok(tasks)
    }

    /// Collect every tool request needed to prepare the supplied tasks without
    /// executing their commands or dependency graphs.
    pub(crate) async fn collect_tool_requests<'t>(
        &self,
        config: &Arc<Config>,
        tasks: impl IntoIterator<Item = &'t Task>,
    ) -> Result<Vec<crate::toolset::ToolRequest>> {
        let tasks = tasks.into_iter().collect::<Vec<_>>();
        let mut requests = vec![];
        let mut seen_config_roots = HashSet::new();

        trace!("Collecting tools from {} tasks", tasks.len());

        for task in tasks {
            requests.extend(task.tool_args()?.into_iter().filter_map(|tool| tool.tvr));

            // Task execution combines task-level tools with the config hierarchy
            // that owns the task. Keep pre-installation consistent with that
            // environment, including file and monorepo tasks.
            let config_root = task
                .cf(config)
                .map(|task_cf| task_cf.config_root())
                .or_else(|| task.config_root.clone());
            if let Some(config_root) = config_root {
                let config_root = canonicalize_path(&config_root);
                if seen_config_roots.insert(config_root.clone()) {
                    requests.extend(
                        self.collect_tools_from_dir(&config_root, &task.name)
                            .await?,
                    );
                }

